import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_f32_t16x16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // Register declarations
    .reg .pred %p0, %p1, %pArow, %pAcol, %pAok, %pAcol2, %pAok2, %pBcol, %pBrow, %pBok, %pBrow2, %pBok2, %pW1, %pW2, %pW;
    .reg .b32 %rTx, %rTy, %rBx, %rBy, %rBdx, %rBdy;
    .reg .b32 %rRow, %rCol, %r0, %r1, %r2, %rN;
    .reg .b32 %rTileCount, %rTile, %rKtile, %rAcol, %rBrow, %rAcol2, %rBrow2;
    .reg .b32 %rSoffA, %rSoffA2, %rSoffB, %rSoffB2, %rK, %rAO, %rBO;
    .reg .b64 %rdA, %rdB, %rdC;
    .reg .b64 %rdAsBase, %rdBsBase;
    .reg .b64 %rd2, %rd3, %rd4, %rd5, %rd6, %rd7, %rd8, %rdTmp, %rdArowPtr, %rdBcolPtr, %rdIncA, %rdIncB;
    .reg .f32 %fAcc, %fA, %fA1, %fA2, %fB, %fB1, %fB2;
    .shared .align 16 .b8 Asub[2048]; // 16*32*4
    .shared .align 16 .b8 Bsub[2048]; // 32*16*4
    // Load parameters
    ld.param.u64 %rdA, [A_ptr];
    ld.param.u64 %rdB, [B_ptr];
    ld.param.u64 %rdC, [C_ptr];
    ld.param.u32 %rN, [N];
    // Thread and block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBdx, %ntid.x;
    mov.u32 %rBdy, %ntid.y;
    // Compute global row and column indices
    mul.lo.u32 %r0, %rBy, %rBdy;
    add.u32 %rRow, %r0, %rTy;
    mul.lo.u32 %r1, %rBx, %rBdx;
    add.u32 %rCol, %r1, %rTx;
    // Initialize accumulator
    mov.f32 %fAcc, 0f00000000;
    // Number of tiles along K: (N + 31) >> 5
    add.u32 %r2, %rN, 31;
    shr.u32 %rTileCount, %r2, 5;
    // Shared memory base addresses
    mov.u64 %rdAsBase, Asub;
    mov.u64 %rdBsBase, Bsub;
    mov.u32 %rTile, 0;
TilesLoop:
    setp.ge.u32 %p0, %rTile, %rTileCount;
    @%p0 bra TilesEnd;
    // Ktile = tile * 32
    shl.b32 %rKtile, %rTile, 5;
    // Compute A and B coordinates for this tile
    add.u32 %rAcol, %rKtile, %rTx;      // A[row, Ktile + tx]
    add.u32 %rAcol2, %rAcol, 16;        // A[row, Ktile + tx + 16]
    add.u32 %rBrow, %rKtile, %rTy;      // B[Ktile + ty, col]
    add.u32 %rBrow2, %rBrow, 16;        // B[Ktile + ty + 16, col]
    // Bounds checks
    setp.lt.u32 %pArow, %rRow, %rN;
    setp.lt.u32 %pAcol, %rAcol, %rN;
    and.pred %pAok, %pArow, %pAcol;
    setp.lt.u32 %pAcol2, %rAcol2, %rN;
    and.pred %pAok2, %pArow, %pAcol2;
    setp.lt.u32 %pBcol, %rCol, %rN;
    setp.lt.u32 %pBrow, %rBrow, %rN;
    and.pred %pBok, %pBcol, %pBrow;
    setp.lt.u32 %pBrow2, %rBrow2, %rN;
    and.pred %pBok2, %pBcol, %pBrow2;
    // Load A element 0 or zero
    @%pAok bra LoadA;
    mov.f32 %fA, 0f00000000;
    bra StoreA;
LoadA:
    // idxA0 = row * N + a_col
    mul.wide.u32 %rd2, %rRow, %rN;      // 64-bit row * N
    cvt.u64.u32 %rdTmp, %rAcol;         // widen a_col
    add.u64 %rd2, %rd2, %rdTmp;         // + a_col
    shl.b64 %rd2, %rd2, 2;              // * sizeof(float)
    add.u64 %rd2, %rd2, %rdA;           // + base A
    ld.global.f32 %fA, [%rd2];
StoreA:
    // Store A0 into shared Asub[ty][tx] with stride 32
    mul.lo.u32 %rSoffA, %rTy, 32;
    add.u32 %rSoffA, %rSoffA, %rTx;     // element index
    cvt.u64.u32 %rdTmp, %rSoffA;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd3, %rdAsBase, %rdTmp;
    st.shared.f32 [%rd3], %fA;
    // Load A element 1 or zero
    @%pAok2 bra LoadA2;
    mov.f32 %fA1, 0f00000000;
    bra StoreA2;
LoadA2:
    // idxA1 = row * N + a_col2
    mul.wide.u32 %rd2, %rRow, %rN;      // 64-bit row * N
    cvt.u64.u32 %rdTmp, %rAcol2;        // widen a_col2
    add.u64 %rd2, %rd2, %rdTmp;         // + a_col2
    shl.b64 %rd2, %rd2, 2;              // * sizeof(float)
    add.u64 %rd2, %rd2, %rdA;           // + base A
    ld.global.f32 %fA1, [%rd2];
StoreA2:
    // Store A1 into shared Asub[ty][tx+16]
    add.u32 %rSoffA2, %rSoffA, 16;      // element index
    cvt.u64.u32 %rdTmp, %rSoffA2;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd3, %rdAsBase, %rdTmp;
    st.shared.f32 [%rd3], %fA1;
    // Load B element 0 or zero
    @%pBok bra LoadB;
    mov.f32 %fB, 0f00000000;
    bra StoreB;
LoadB:
    // idxB0 = b_row * N + col
    mul.wide.u32 %rd4, %rBrow, %rN;     // 64-bit b_row * N
    cvt.u64.u32 %rdTmp, %rCol;          // widen col
    add.u64 %rd4, %rd4, %rdTmp;         // + col
    shl.b64 %rd4, %rd4, 2;              // * sizeof(float)
    add.u64 %rd4, %rd4, %rdB;           // + base B
    ld.global.f32 %fB, [%rd4];
StoreB:
    // Store B0 into shared Bsub[ty][tx] (K-major: 32x16)
    mul.lo.u32 %rSoffB, %rTy, 16;       // element index
    add.u32 %rSoffB, %rSoffB, %rTx;
    cvt.u64.u32 %rdTmp, %rSoffB;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd5, %rdBsBase, %rdTmp;
    st.shared.f32 [%rd5], %fB;
    // Load B element 1 or zero
    @%pBok2 bra LoadB2;
    mov.f32 %fB1, 0f00000000;
    bra StoreB2;
LoadB2:
    // idxB1 = b_row2 * N + col
    mul.wide.u32 %rd4, %rBrow2, %rN;    // 64-bit b_row2 * N
    cvt.u64.u32 %rdTmp, %rCol;          // widen col
    add.u64 %rd4, %rd4, %rdTmp;         // + col
    shl.b64 %rd4, %rd4, 2;              // * sizeof(float)
    add.u64 %rd4, %rd4, %rdB;           // + base B
    ld.global.f32 %fB1, [%rd4];
StoreB2:
    // Store B1 into shared Bsub[ty+16][tx] -> add 16*16 elements
    add.u32 %rSoffB2, %rSoffB, 256;     // element index offset for +16 rows
    cvt.u64.u32 %rdTmp, %rSoffB2;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd5, %rdBsBase, %rdTmp;
    st.shared.f32 [%rd5], %fB1;
    // Synchronize to ensure all shared loads complete
    bar.sync 0;
    // Inner product over the tile K dimension (k = 0..31)
    // Initialize K loop with pointer arithmetic and unrolling by 4
    // Precompute shared memory base pointers for this thread
    mul.lo.u32 %rAO, %rTy, 32;
    cvt.u64.u32 %rdTmp, %rAO;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rdArowPtr, %rdAsBase, %rdTmp;      // Asub[ty][0]
    cvt.u64.u32 %rdTmp, %rTx;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rdBcolPtr, %rdBsBase, %rdTmp;      // Bsub[0][tx]
    mov.u64 %rdIncA, 4;
    mov.u64 %rdIncB, 64;
    mov.u32 %rK, 0;
KLoop:
    setp.ge.u32 %p1, %rK, 32;
    @%p1 bra KEnd;
    // Unrolled step 0
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 1
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 2
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 3
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    bra KLoop;
KEnd:
    // Synchronize before loading the next tile
    bar.sync 0;
    add.u32 %rTile, %rTile, 1;
    bra TilesLoop;
TilesEnd:
    // Write result if within bounds
    setp.lt.u32 %pW1, %rRow, %rN;
    setp.lt.u32 %pW2, %rCol, %rN;
    and.pred %pW, %pW1, %pW2;
    @!%pW bra End;
    mul.wide.u32 %rd8, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rCol;
    add.u64 %rd8, %rd8, %rdTmp;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd8, %rd8, %rdC;
    st.global.f32 [%rd8], %fAcc;
End:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_f32_t16x16")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.dim() == 2 and B.dim() == 2 and A.size(0) == A.size(1) and B.size(0) == B.size(1), "Square matrices expected"
        assert A.size(1) == B.size(0), "Incompatible shapes for matmul"
        N = A.size(0)
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        block_x, block_y, block_z = 16, 16, 1
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y
        grid_z = 1

        module = _get_ptx_module()
        module.launch(
            "matmul_f32_t16x16",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

