    cvt.u64.u32 %rdTmp, %rAcol2;        // widen a_col2
    add.u64 %rd2, %rd2, %rdTmp;         // + a_col2
    shl.b64 %rd2, %rd2, 2;              // * sizeof(float)
    add.u64 %rd2, %rd2, %rdA;           // + base A
    ld.global.f32 %fA1, [%rd2];
StoreA2:
    // Store A1 into shared Asub[ty][tx+16]
    add.u32 %rSoffA2, %rSoffA, 16;      // element index
    cvt.u64.u32 %rdTmp, %rSoffA2;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd3, %rdAsBase, %rdTmp;
    st.shared.f32 [%rd3], %fA1;
