    mul.wide.u32 %rd4, %rBrow, %rN;     // 64-bit b_row * N
    cvt.u64.u32 %rdTmp, %rCol;          // widen col
    add.u64 %rd4, %rd4, %rdTmp;         // + col
    shl.b64 %rd4, %rd4, 2;              // * sizeof(float)
    add.u64 %rd4, %rd4, %rdB;           // + base B
    ld.global.f32 %fB, [%rd4];
StoreB:
