    add.u32 %rSoffB2, %rSoffB, 256;     // element index offset for +16 rows
    cvt.u64.u32 %rdTmp, %rSoffB2;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd5, %rdBsBase, %rdTmp;
    st.shared.f32 [%rd5], %fB1;
